/* @lc app=leetcode id=3490 lang=kotlin */ class Solution { fun cnt(G: List<Array<IntArray>>, N: Int, s: Int): Int = N.toString().map { it - '0' }.let { dg -> dg.size.let { L -> (1 until L).sumOf { len -> (1..9).sumOf { d -> if (d <= s) G[len - 1][s - d][d % s] else 0 } } + dg.indices.fold(Triple(0, 1 % s, 0)) { (sp, pp, acc), i -> Triple(sp + dg[i], pp * dg[i] % s, acc + (if (i == 0) 1 else 0).let { st -> (st until dg[i]).sumOf { d -> if (sp + d <= s) G[L - 1 - i][s - sp - d][pp * d % s] else 0 } }) }.let { (sp, pp, acc) -> acc + (if (sp == s && pp == 0) 1 else 0) } } } fun beautifulNumbers(l: Int, r: Int): Int = (1..81).sumOf { s -> (1..9).fold(listOf(Array(s + 1) { rem -> IntArray(s) { pm -> if (rem == 0 && pm == 0) 1 else 0 } })) { acc, _ -> acc + listOf(Array(s + 1) { rem -> IntArray(s) { pm -> (0..minOf(9, rem)).sumOf { dg -> acc.last()[rem - dg][(pm * dg) % s] } } }) }.let { G -> cnt(G, r, s) - cnt(G, l - 1, s) } } }